export function findImport(orgId: OrgId, importKey: string): IssueImportResult | null {
  const row = getDb().select().from(issueImports).where(and(eq(issueImports.orgId, orgId), eq(issueImports.importKey, importKey))).get();
  return row ? { ...JSON.parse(row.result) as IssueImportResult, replayed: true } : null;
}

/** No asynchronous work may escape this transaction: labels, issues and the receipt commit together. */
export function insertImport(input: ImportIssuesInput, authorId: UserId, plan: PlanId, projectKey: string): IssueImportResult {
  return getDb().transaction((db) => {
    const replay = findImport(input.orgId, input.importKey);
    if (replay) return replay;
    const scope = and(eq(issues.orgId, input.orgId), eq(issues.projectId, input.projectId));
    const used = db.select({ value: count() }).from(issues).where(and(scope, isNull(issues.archivedAt))).get()?.value ?? 0;
    if (wouldExceedLimit(plan, \"issuesPerProject\", used, input.rows.length)) {
      throw new Error("'`Plan ${plan} allows no more issues in project ${projectKey}`);
    }
    const firstNumber = (db.select({ value: sql<number | null>`max(${issues.number})` }).from(issues).where(scope).get()?.value ?? 0) + 1;
    const activeMembers = db.select({ email: users.email, userId: users.id }).from(members)
      .innerJoin(users, eq(users.id, members.userId))
      .where(and(eq(members.orgId, input.orgId), eq(members.status, "active"), isNull(members.archivedAt))).all();
    const assignees = new Map(activeMembers.map((member) => [member.email.toLowerCase(), member.userId as UserId]));
    const labelIds = new Map(db.select().from(labels).where(eq(labels.orgId, input.orgId)).all().map((label) => [label.name, label.id as LabelId]));
    const stamp = toIsoTimestamp(new Date());
    const imported = input.rows.map((inputRow, index) => {
      const rowLabels = [...new Set(inputRow.labels)].map((name) => {
        let id = labelIds.get(name);
        if (!id) {
          id = newId() as LabelId;
          db.insert(labels).values({ id, orgId: input.orgId, name, description: null, createdAt: stamp, updatedAt: stamp }).run();
          labelIds.set(name, id);
        }
        return id;
      });
      const row = db.insert(issues).values({
        id: newId(), orgId: input.orgId, projectId: input.projectId,
        number: firstNumber + index, title: inputRow.title, description: inputRow.description,
        status: inputRow.status, priority: inputRow.priority, dueAt: inputRow.dueAt,
        authorId, assigneeId: inputRow.assigneeEmail ? assignees.get(inputRow.assigneeEmail.toLowerCase()) ?? null : null,
        parentId: null, estimate: null, startedAt: null, completedAt: null,
        createdAt: stamp, updatedAt: stamp,
      }).returning().get();
      if (rowLabels.length) db.insert(issueLabels).values(rowLabels.map((labelId) => ({ orgId: input.orgId, issueId: row.id, labelId }))).run();
      return toIssue(row, rowLabels);
    });
    const result: IssueImportResult = { importKey: input.importKey, projectId: input.projectId, issues: imported, replayed: false };
    db.insert(issueImports).values({ orgId: input.orgId, importKey: input.importKey, projectId: input.projectId, result: JSON.stringify(result) }).run();
    return result;
  });
}
