/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

/**
 * ULID generation and validation. Every branded id in the app is produced
 * here, so ids sort lexicographically by creation time and the repositories
 * can use them as pagination cursors without a separate sort column.
 */
/** Crockford base32, minus I, L, O and U. */
const ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";
const TIME_LENGTH = 10;
const RANDOM_LENGTH = 16;

const ULID_PATTERN = /^[0-9A-HJKMNP-TV-Z]{26}$/;

function encodeTime(time: number): string {
  let remaining = time;
  let out = "";
  for (let i = 0; i < TIME_LENGTH; i += 1) {
    const mod = remaining % 32;
    out = ALPHABET[mod] + out;
    remaining = (remaining - mod) / 32;
  }
  return out;
}

function encodeRandom(next: () => number): string {
  let out = "";
  for (let i = 0; i < RANDOM_LENGTH; i += 1) {
    out += ALPHABET[next() % 32];
  }
  return out;
}

/** A fresh, monotonically-sortable ULID. Uses the Web Crypto API so the same
 *  implementation runs on the server, in the browser and on the edge. */
export function newId(): string {
  const bytes = new Uint8Array(RANDOM_LENGTH);
  globalThis.crypto.getRandomValues(bytes);
  let cursor = 0;
  return encodeTime(Date.now()) + encodeRandom(() => bytes[cursor++] ?? 0);
}

export function isUlid(value: string): boolean {
  return ULID_PATTERN.test(value);
}

/**
 * A deterministic id generator for tests and the seed script: same seed,
 * same sequence of ids. Uses a small xorshift PRNG and a fixed timestamp so
 * fixtures are byte-stable across runs.
 */
export function idFactory(seed: number): () => string {
  let state = (seed | 0) || 0x2545_f491;
  let counter = 0;

  const next = (): number => {
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    return Math.abs(state);
  };

  return () => {
    counter += 1;
    // A fixed epoch keeps seeded ids stable; the counter keeps them ordered.
    return encodeTime(1_700_000_000_000 + counter) + encodeRandom(next);
  };
}

