it(\"imports in order, persists replays, and fans out only batch effects\", async () => {
  const tenant = await createTenant(\"importbatch\");
  const input = importIssuesSchema.parse({ orgId: tenant.org.id, projectId: tenant.project.id, importKey: \"upload-one\", rows: [
    { title: \"First imported\", assigneeEmail: \"ADMIN@IMPORTBATCH.TEST\", labels: [\"Bug\", \"Bug\"] },
    { title: \"Second imported\", labels: [\"Bug\", \"bug\"], status: \"done\" },
  ] });
  const batches: unknown[] = [], creates: unknown[] = [];
  const off = subscribe(\"issues.imported\", (event) => { batches.push(event); });
  const offCreate = subscribe(\"issue.created\", (event) => { creates.push(event); });
  try {
    const result = await importIssues(tenant.actors.member, input);
    expect(result.issues.map((issue) => issue.number)).toEqual([1, 2]);
    expect(result.issues[0].assigneeId).toBe(tenant.userIds.admin);
    expect(result.issues[0].labelIds).toHaveLength(1);
    expect(await listLabels(tenant.org.id)).toHaveLength(2);
    expect(batches).toHaveLength(1);
    expect(creates).toHaveLength(0);
    const replay = await importIssues(tenant.actors.member, { ...input, rows: [input.rows[1]] });
    expect(replay).toEqual({ ...result, replayed: true });
    expect(batches).toHaveLength(1);
    const db = getDb();
    expect(db.select().from(searchIndex).where(eq(searchIndex.orgId, tenant.org.id)).all()).toHaveLength(2);
    const audit = db.select().from(activityEvents).where(eq(activityEvents.orgId, tenant.org.id)).all();
    expect(audit).toHaveLength(1);
    expect(audit[0]).toMatchObject({ action: \"issues.imported\", actorId: tenant.userIds.member, subjectKind: \"project\", subjectId: tenant.project.id });
    expect(JSON.parse(audit[0].metadata)).toEqual({ count: 2, importKey: input.importKey });
    expect((await getUsage(tenant.org.id)).issuesUsed).toBe(2);
    expect((await recomputeUsage(tenant.org.id)).issuesUsed).toBe(2);
    expect(db.select().from(notifications).where(eq(notifications.orgId, tenant.org.id)).all()).toHaveLength(0);
    expect(db.select().from(webhookDeliveries).where(eq(webhookDeliveries.orgId, tenant.org.id)).all()).toHaveLength(0);
    expect((await createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id))).number).toBe(3);
  } finally { off(); offCreate(); }
});

it(\"refuses a batch without spending its key when the rate allowance is insufficient\", async () => {
  const tenant = await createTenant(\"importrate\", \"free\");
  resetRateLimits();
  await consumeRateLimit(tenant.org.id, \"issue:create\", 59);
  const input = importIssuesSchema.parse({ orgId: tenant.org.id, projectId: tenant.project.id, importKey: \"retry-upload\", rows: [{ title: \"First issue\" }, { title: \"Second issue\" }] });
  await expect(importIssues(tenant.actors.member, input)).rejects.toThrow(/rate limit/);
